def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest().upper()


def _browser_executable() -> Path:
    configured = os.environ.get("PUPPETEER_EXECUTABLE_PATH", "").strip()
    candidates = [
        Path(configured) if configured else Path("__missing__"),
        Path(r"C:\Program Files\Google\Chrome\Application\chrome.exe"),
        Path(r"C:\Program Files\Microsoft\Edge\Application\msedge.exe"),
        Path(r"C:\Program Files (x86)\Google\Chrome\Application\chrome.exe"),
        Path(r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe"),
    ]
    browser = next((candidate.resolve() for candidate in candidates if candidate.is_file()), None)
    if browser is None:
        raise RuntimeError("An already-installed Chrome or Edge executable is required for Mermaid rendering.")
    return browser


def _mermaid_cli() -> str:
    configured = os.environ.get("EVIDENCE_LANE_MERMAID_CLI", "").strip()
    executable = shutil.which(configured or "mmdc")
    if executable:
        return executable
    if configured and Path(configured).is_file():
