def _parse_uses_value(raw: str) -> str | None:
    value = raw.strip()
    if not value:
        return None
    if value[0] in {'"', "'"}:
        quote = value[0]
        end = value.find(quote, 1)
        if end < 0:
            return None
        trailing = value[end + 1 :].strip()
        if trailing and not trailing.startswith("#"):
            return None
        return value[1:end]
    return value.split("#", 1)[0].strip().split(maxsplit=1)[0]


