def _chunks(text: str) -> Iterable[tuple[int, int, str]]:
    if not text:
        return
    start = 0
    ordinal = 0
    step = CHUNK_CHARS - CHUNK_OVERLAP
    while start < len(text):
        end = min(len(text), start + CHUNK_CHARS)
        yield ordinal, start, text[start:end]
        if end == len(text):
            break
        start += step
        ordinal += 1


