def physical_table_node_ids(projection: dict[str, Any]) -> dict[str, str]:
    """Map table names to stable MMD/DOT IDs from projection ordinals."""

    return {
        str(row["table"]): f'PHYSICAL_TABLE_{int(row["ordinal"]):03d}'
        for row in projection["tables"]
    }


def physical_table_group_id(row: dict[str, Any]) -> str:
    """Return the compact visual group for one exact physical table row."""

    table = str(row["table"])
    role = str(row["role"])
    if role == "core_contract":
        return "PHYSICAL_GROUP_CORE"
    if table.startswith("git_"):
        return "PHYSICAL_GROUP_GIT"
    if role == "sqlite_engine_auxiliary":
        return "PHYSICAL_GROUP_AUXILIARY"
    return "PHYSICAL_GROUP_LANE"

def physical_table_groups(
    projection: dict[str, Any],
) -> dict[str, list[dict[str, Any]]]:
    """Group tables without changing their canonical projection order."""

    groups: dict[str, list[dict[str, Any]]] = {}
    for row in projection["tables"]:
        groups.setdefault(physical_table_group_id(row), []).append(row)
    return groups

def unseal_archive(
    payload: bytes, *, key_value: str | None
) -> tuple[bytes, dict[str, Any]]:
    try:
        envelope = json.loads(payload.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return payload, {"encryption": "NONE", "archive_sha256": sha256_bytes(payload)}
    if envelope.get("schema") != "evidence-lane.pv-aesgcm-envelope.v1":
        return payload, {"encryption": "NONE", "archive_sha256": sha256_bytes(payload)}
    require(
        bool(key_value),
        "DRIVE_DECRYPTION_KEY_REQUIRED",
        "This sealed PV requires the user-owned Drive encryption key.",
        status="BLOCKED",
    )
    key = _decode_key(key_value or "")
    nonce = base64.urlsafe_b64decode(envelope["nonce_b64"])
    associated_data = base64.urlsafe_b64decode(envelope["associated_data_b64"])
    ciphertext = base64.urlsafe_b64decode(envelope["ciphertext_b64"])
    try:
        archive = AESGCM(key).decrypt(nonce, ciphertext, associated_data)
    except Exception as exc:
        raise EvidenceLaneError(
            "DRIVE_DECRYPTION_FAILED",
            "The sealed PV could not be authenticated and decrypted.",
            status="MISMATCH",
        ) from exc
    return archive, json.loads(associated_data.decode("utf-8"))

