            for match in re.finditer(r"(?m)^\s*([A-Za-z0-9_.~/-]+)\s+(v[^\s]+)", text):
                add("go", match.group(1), match.group(2), "require")
        elif suffix in _MANIFEST_SUFFIXES:
            for match in re.finditer(
