def transition(
    current: SessionState,
    event: LifecycleEvent,
    target: SessionState,
) -> SessionState:
    allowed = TRANSITION_LAW[event]
    require(
        (current, target) in allowed,
        "SESSION_TRANSITION_NOT_ALLOWED",
        "The requested lifecycle transition is not present in the canonical law.",
        status="BLOCKED",
        current=current.value,
        event=event.value,
        target=target.value,
        allowed=[
            {"from": source.value, "to": destination.value}
            for source, destination in sorted(
                allowed, key=lambda pair: (pair[0].value, pair[1].value)
            )
        ],
    )
    return target


def transition_catalog() -> dict[str, Any]:
    return {
        "schema": "evidence-lane.session-transition-law.v1",
        "single_authority": True,
        "events": {
            event.value: [
                {"from": source.value, "to": target.value}
                for source, target in sorted(
                    pairs, key=lambda pair: (pair[0].value, pair[1].value)
                )
            ]
            for event, pairs in TRANSITION_LAW.items()
        },
    }

class _ProjectLock:
    _process_locks: ClassVar[dict[str, threading.RLock]] = {}
    _guard: ClassVar[threading.Lock] = threading.Lock()

    def __init__(self, path: Path, *, timeout: float = 10.0) -> None:
        self.path = path
        self.timeout = timeout
        with self._guard:
            self._lock = self._process_locks.setdefault(str(path), threading.RLock())
        self._fd: int | None = None

    def __enter__(self) -> Self:
        self._lock.acquire()
        deadline = time.monotonic() + self.timeout
        self.path.parent.mkdir(parents=True, exist_ok=True)
        while True:
            try:
                self._fd = os.open(
                    self.path,
                    os.O_CREAT | os.O_EXCL | os.O_WRONLY,
                )
                os.write(self._fd, str(os.getpid()).encode("ascii"))
                return self
            except FileExistsError:
                if time.monotonic() >= deadline:
                    self._lock.release()
                    raise EvidenceLaneError(
                        "PROJECT_STORE_LOCK_TIMEOUT",
                        "The project store remained locked.",
                        status="BLOCKED",
                        details={"lock": str(self.path)},
                    )
                time.sleep(0.05)

    def __exit__(self, exc_type: object, exc: object, traceback: object) -> None:
        try:
            if self._fd is not None:
                os.close(self._fd)
