def _binary_identity(path: str | None) -> dict[str, Any] | None:
    if not path:
        return None
    resolved = Path(path).resolve()
    if not resolved.is_file():
        return None
    return {
        "name": resolved.name,
        "bytes": resolved.stat().st_size,
        "sha256": sha256_file(resolved),
    }


